Cutting each class form to 11 directions loses about 3.5 points, so I'll use exact QDA: layer 1 holds 18 linear pass-through units (silu(x+20) is nearly x+20) plus 30 small-input squaring units (silu(t)-t/2 is about t^2/4); layer 2 holds 3 score pass-through units plus 24 more squaring units. Together they give the 54 directions needed for the three class-vs-class-0 quadratic forms. This block builds the weights, checks them in float32 against QDA, and saves them; I expect to match QDA's 91.5% training accuracy.
```python
exec(open("h.py").read())
print("max|x|",np.abs(X).max())
m=qda_fit(X,y); P=parts(m)
D0,b0,d0=P[0]
dirs=[]  # (k, lam, u)
for k in (1,2,3):
    Dk,bk,dk=P[k]; lam,V=np.linalg.eigh(Dk-D0)
    for i in range(18): dirs.append((k,lam[i],V[:,i]))
dirs.sort(key=lambda t:-abs(t[1]))
S1=dirs[:30]; S2=dirs[30:]
C=20.0; C2=30.0; s=0.1
W1=np.zeros((48,18)); b1=np.zeros(48)
W1[:18]=np.eye(18); b1[:18]=C
lin={k:(P[k][1]-b0).copy() for k in (1,2,3)}
delta={k:P[k][2]-d0 for k in (1,2,3)}
q1w={k:np.zeros(48) for k in (1,2,3)}  # weights from layer1 outputs into score unit
for j,(k,lam,u) in enumerate(S1):
    eps=s/np.std(X@u); W1[18+j]=eps*u
    q1w[k][18+j]+=-2*lam/eps**2; lin[k]+=lam/eps*u
W2=np.zeros((48,48)); b2=np.zeros(48)
W3=np.zeros((4,48)); b3=np.zeros(4)
for j,(k,lam,u) in enumerate(S2):
    eps=s/np.std(X@u); W2[3+j,:18]=eps*u; b2[3+j]=-C*eps*u.sum()
    W3[k,3+j]+=-2*lam/eps**2; lin[k]+=lam/eps*u
# score pre-activation L_k (before alpha)
Lrows={}
for k in (1,2,3):
    r=q1w[k].copy(); r[:18]+=lin[k]; Lrows[k]=(r,-C*lin[k].sum())
def silu(z): return z/(1+np.exp(-z))
H1=silu(X@W1.T+b1)
Ls=np.stack([H1@Lrows[k][0]+Lrows[k][1] for k in (1,2,3)],1)
alpha=10/np.abs(Ls).max(); print("maxL",np.abs(Ls).max(),"alpha",alpha)
for i,k in enumerate((1,2,3)):
    W2[i]=alpha*Lrows[k][0]; b2[i]=alpha*Lrows[k][1]+C2
    W3[k,i]=1/alpha; b3[k]=-C2/alpha+delta[k]
Wd={"l1.weight":W1,"l1.bias":b1,"l2.weight":W2,"l2.bias":b2,"l3.weight":W3,"l3.bias":b3}
def fwd(Xin,dt):
    f=lambda n:Wd[n].astype(dt); Xi=Xin.astype(dt)
    h=silu(Xi@f("l1.weight").T+f("l1.bias")); h=silu(h@f("l2.weight").T+f("l2.bias"))
    return h@f("l3.weight").T+f("l3.bias")
mus,As,cs=m
true=np.stack([-0.5*np.einsum('ij,jk,ik->i',X-mu,A,X-mu)+c for mu,A,c in zip(mus,As,cs)],1); true-=true[:,:1]
for dt in (np.float64,np.float32):
    o=fwd(X,dt); print(dt.__name__,"acc",(o.argmax(1)==y).mean(),"agree",(o.argmax(1)==true.argmax(1)).mean(),"maxerr",np.abs(o-true).max())
for n,a in Wd.items(): save_edit(n,a.astype(np.float32))
